<?php
declare(strict_types=1);
function handle_post(string $path): void {
 verify_csrf();$ip=$_SERVER['REMOTE_ADDR']??'local';
 if($path==='/login'){
 rate_limit('login-ip:'.$ip,30,900);$email=email_input();rate_limit('login-mail:'.$email,10,900);$u=row('SELECT * FROM users WHERE email=?',[$email]);$password=(string)($_POST['password']??'');
 $dummy='$2y$10$BFOJrCG9bZGi6KTmI4MeT.WXH1ScGrbS3Y7ySxboB1RGcjdk34kYO';$ok=password_verify($password,$u['password_hash']??$dummy);
 if(!$u||!$ok||$u['status']!=='active'){audit('auth.login_failed');throw new InvalidArgumentException('The email or password is incorrect, or the account is inactive.');}
 if($u['totp_confirmed']){session_regenerate_id(true);$_SESSION['pending_mfa']=['user_id'=>(int)$u['id'],'auth_version'=>(int)$u['auth_version'],'expires'=>time()+300];go('two-factor');}complete_login($u);
 }
 if($path==='/register'){
 rate_limit('register:'.$ip,6,3600);$name=text_input('name',140);$email=email_input();$phone=phone_input();$pass=(string)($_POST['password']??'');password_valid($pass);if($pass!==($_POST['password_confirm']??''))throw new InvalidArgumentException('The passwords do not match.');if(empty($_POST['consent']))throw new InvalidArgumentException('Please accept the privacy notice.');if(row('SELECT id FROM users WHERE email=?',[$email]))throw new InvalidArgumentException('This email is already registered. Sign in or reset your password.');
 $id=insert('users',['name'=>$name,'email'=>$email,'phone'=>$phone,'password_hash'=>password_hash($pass,PASSWORD_DEFAULT),'role'=>'citizen','status'=>'active','created_at'=>now()]);session_regenerate_id(true);$_SESSION['user_id']=$id;$_SESSION['auth_version']=1;$_SESSION['last_seen']=time();record_device_session($id);notify($id,'Welcome to CivicFlow','Your account is ready. Browse the service directory to make your first request.','services');queue_email_verification(row('SELECT * FROM users WHERE id=?',[$id]));audit('auth.registered',$id);flash('Welcome. Your citizen account is ready.');go('dashboard');
 }
 if($path==='/forgot-password'){
 rate_limit('reset-ip:'.$ip,6,900);$email=email_input();$u=row('SELECT * FROM users WHERE email=? AND status=?',[$email,'active']);if($u){$token=bin2hex(random_bytes(32));sql('UPDATE password_resets SET used_at=? WHERE user_id=? AND used_at IS NULL',[now(),$u['id']]);insert('password_resets',['user_id'=>$u['id'],'token_hash'=>hash('sha256',$token),'expires_at'=>date('Y-m-d H:i:s',time()+3600),'used_at'=>null]);insert('outbox',['user_id'=>$u['id'],'channel'=>'email','recipient'=>$u['email'],'subject'=>'Reset your CivicFlow password','body'=>'Use this single-use link within one hour: '.url('reset-password?token='.$token).' . If you did not request it, ignore this email.','state'=>setting('email_enabled','0')==='1'?'pending':'configuration_required','created_at'=>now()]);audit('auth.reset_requested',(int)$u['id']);}
 flash('If an active account matches, password reset instructions will be emailed. If no email arrives, contact the portal administrator.');go('forgot-password');
 }
 if($path==='/reset-password'){
 rate_limit('reset-submit:'.$ip,12,900);$token=text_input('token',100);$reset=row('SELECT * FROM password_resets WHERE token_hash=? AND used_at IS NULL AND expires_at>?',[hash('sha256',$token),now()]);if(!$reset)throw new InvalidArgumentException('This reset link is invalid or expired. Request a new one.');$p=(string)($_POST['password']??'');password_valid($p);if($p!==($_POST['password_confirm']??''))throw new InvalidArgumentException('The passwords do not match.');db()->beginTransaction();try{$q=sql('UPDATE password_resets SET used_at=? WHERE id=? AND used_at IS NULL AND expires_at>?',[now(),$reset['id'],now()]);if(!$q->rowCount())throw new InvalidArgumentException('This link has already been used.');sql('UPDATE users SET password_hash=?,auth_version=auth_version+1 WHERE id=?',[password_hash($p,PASSWORD_DEFAULT),$reset['user_id']]);audit('auth.password_reset',(int)$reset['user_id']);db()->commit();}catch(Throwable $ex){if(db()->inTransaction())db()->rollBack();throw $ex;}flash('Password updated. Sign in with your new password.');go('login');
 }
 if($path==='/verify-email'){
 rate_limit('verify-email:'.$ip,20,900);$token=text_input('token',100);$record=row('SELECT * FROM email_verifications WHERE token_hash=? AND used_at IS NULL AND expires_at>?',[hash('sha256',$token),now()]);if(!$record)throw new InvalidArgumentException('This verification link is invalid or expired. Request another from your profile.');db()->beginTransaction();try{$q=sql('UPDATE email_verifications SET used_at=? WHERE id=? AND used_at IS NULL AND expires_at>?',[now(),$record['id'],now()]);if(!$q->rowCount())throw new InvalidArgumentException('This verification link has already been used.');sql('UPDATE users SET email_verified_at=? WHERE id=?',[now(),$record['user_id']]);audit('auth.email_verified',(int)$record['user_id']);db()->commit();}catch(Throwable $ex){if(db()->inTransaction())db()->rollBack();throw $ex;}flash('Your email address is verified.');go('login');
 }
 if($path==='/track'){
 rate_limit('track:'.$ip,20,600);$ref=strtoupper(text_input('reference',50));$code=strtoupper(text_input('tracking_code',64));$r=row('SELECT * FROM requests WHERE reference=?',[$ref]);if(!$r||!hash_equals($r['access_token'],$code)||$r['status']==='draft')throw new InvalidArgumentException('No matching request. Check the reference and private tracking code.');$_SESSION['public_track']=['id'=>(int)$r['id'],'expires'=>time()+600];go('track');
 }
 if($path==='/api/assistant'){
 rate_limit('assistant:'.($ip.':'.($_SESSION['user_id']??'guest')),20,300);$q=text_input('question',1500);json_out(assistant_answer($q,($_POST['use_ai']??'')==='1'));
 }
 $u=require_user();
 if(str_starts_with($path,'/profile/security/')||$path==='/profile/sessions/revoke')account_security_post($path,$u);
 if($path==='/logout'){sql('UPDATE device_sessions SET revoked_at=? WHERE token_hash=?',[now(),hash('sha256',$_SESSION['device_token']??'')]);audit('auth.logout',(int)$u['id']);$_SESSION=[];session_regenerate_id(true);go('login');}
 if($path==='/requests/new'||preg_match('~^/requests/(\d+)/edit$~',$path,$m)){
 require_permission('requests.create');if(empty($_POST['confirmation']))throw new InvalidArgumentException('Confirm the accuracy of your request before saving.');rate_limit('request-create:'.$u['id'],30,3600);$nonce=(string)($_POST['_nonce']??'');if(!isset($_SESSION['request_forms'][$nonce]))throw new InvalidArgumentException('This form expired. Open a fresh request form.');if(is_int($_SESSION['request_forms'][$nonce]))go('requests/'.$_SESSION['request_forms'][$nonce]);
 $priority=text_input('priority',20);if(!in_array($priority,['normal','high','urgent'],true))throw new InvalidArgumentException('Invalid priority.');
 $data=['service_id'=>(int)($_POST['service_id']??0),'subject'=>text_input('subject',180),'description'=>text_input('description',10000),'location'=>text_input('location',200),'state_name'=>text_input('state_name',60),'organisation'=>text_input('organisation',180,false),'priority'=>$priority,'version'=>(int)($_POST['version']??0)];
 $id=submit_request($u,$data,validated_uploads(),isset($m[1])?(int)$m[1]:null,($_POST['intent']??'')==='draft');$_SESSION['request_forms'][$nonce]=$id;flash(($_POST['intent']??'')==='draft'?'Draft saved. Submit it when ready.':'Request submitted. Your reference and private tracking code are shown below.');go('requests/'.$id);
 }
 if(preg_match('~^/requests/(\d+)/(status|reply|assign|withdraw|reopen|feedback)$~',$path,$m)){
 $r=scoped_request((int)$m[1],$u);$id=(int)$r['id'];$action=$m[2];$version=(int)($_POST['version']??0);
 if($action==='status'){require_permission(in_array((string)($_POST['status']??''),['approved','resolved','rejected'],true)?'requests.decide':'requests.review');change_status($r,$u,text_input('status',30),text_input('message',5000),$version);flash('Status updated and citizen notified.');}
 elseif($action==='reply'){require_permission(isset($_POST['internal'])?'requests.internal_notes':'requests.message');$files=validated_uploads();$message=text_input('message',5000);add_reply($r,$u,$message,$files,isset($_POST['internal']));flash('Message added.');}
 elseif($action==='assign'){
 require_permission('requests.assign');if(in_array($r['status'],array_merge(FINAL_STATUSES,['draft']),true))throw new InvalidArgumentException('This request cannot be reassigned.');$dept=(int)($_POST['department_id']??$r['department_id']);if($dept!==(int)$r['department_id']&&!can('requests.reroute',$u))throw new InvalidArgumentException('Only administrators can reroute between departments.');if(!row('SELECT id FROM departments WHERE id=?',[$dept]))throw new InvalidArgumentException('Choose a valid department.');$off=(int)($_POST['assigned_to']??0);if($off&&(!($candidate=row("SELECT * FROM users WHERE id=? AND status='active' AND department_id=?",[$off,$dept]))||!can('requests.review',$candidate)))throw new InvalidArgumentException('The officer must belong to the selected department.');$note=text_input('message',1000);db()->beginTransaction();try{$q=sql('UPDATE requests SET department_id=?,assigned_to=?,updated_at=?,version=version+1 WHERE id=? AND version=?',[$dept,$off?:null,now(),$id,$version]);if(!$q->rowCount())throw new InvalidArgumentException('This request changed. Reload before assigning.');event($id,(int)$u['id'],$r['status'],$r['status'],'Routing updated. '.$note);if($off)notify($off,'Request assigned',$r['reference'].' has been assigned to you.','requests/'.$id,$id,false);audit('request.assigned',$id,['department'=>$dept,'officer'=>$off]);db()->commit();}catch(Throwable $ex){if(db()->inTransaction())db()->rollBack();throw $ex;}flash('Assignment updated.');
 }
 elseif($action==='withdraw'||$action==='reopen'){
 require_permission($action==='withdraw'?'requests.withdraw':'requests.reopen');if((int)$r['user_id']!==(int)$u['id'])abort_page(403,'Only the request owner can do this.');$reason=text_input('message',2000);
 if($action==='withdraw'&&!in_array($r['status'],['draft','submitted','needs_information'],true))throw new InvalidArgumentException('This request cannot be withdrawn at its current stage.');
 if($action==='reopen'&&($r['kind']!=='complaint'||$r['status']!=='resolved'))throw new InvalidArgumentException('Only a resolved complaint can be reopened.');
 $to=$action==='withdraw'?'withdrawn':'submitted';$svc=row('SELECT sla_hours FROM services WHERE id=?',[$r['service_id']]);db()->beginTransaction();try{$q=sql('UPDATE requests SET status=?,closed_at=?,due_at=?,escalated_at=NULL,updated_at=?,version=version+1 WHERE id=? AND version=?',[$to,$to==='withdrawn'?now():null,$to==='submitted'?date('Y-m-d H:i:s',time()+(int)$svc['sla_hours']*3600):$r['due_at'],now(),$id,$version]);if(!$q->rowCount())throw new InvalidArgumentException('This request changed. Reload before continuing.');event($id,(int)$u['id'],$r['status'],$to,label($action).': '.$reason);if($r['assigned_to'])notify((int)$r['assigned_to'],'Citizen '.($action==='reopen'?'reopened':'withdrew').' a request',$r['reference'].': '.$reason,'requests/'.$id,$id,false);if($action==='reopen')sql('DELETE FROM feedback WHERE request_id=?',[$id]);audit('request.'.$action,$id);db()->commit();}catch(Throwable $ex){if(db()->inTransaction())db()->rollBack();throw $ex;}flash('Request '.($action==='reopen'?'reopened':'withdrawn').'.');
 }
 elseif($action==='feedback'){
 require_permission('requests.feedback');if((int)$r['user_id']!==(int)$u['id']||!in_array($r['status'],['approved','resolved','rejected'],true))throw new InvalidArgumentException('Feedback is available after a decision.');$rating=(int)($_POST['rating']??0);if($rating<1||$rating>5)throw new InvalidArgumentException('Choose a rating between one and five.');$comment=text_input('comment',2000,false);if(row('SELECT id FROM feedback WHERE request_id=?',[$id]))throw new InvalidArgumentException('Feedback has already been recorded.');insert('feedback',['request_id'=>$id,'user_id'=>$u['id'],'rating'=>$rating,'comment'=>$comment,'created_at'=>now()]);audit('request.feedback',$id,['rating'=>$rating]);flash('Thank you. Your feedback has been recorded.');
 }
 go('requests/'.$id);
 }
 if($path==='/notifications/read'){sql('UPDATE notifications SET read_at=? WHERE user_id=? AND read_at IS NULL',[now(),$u['id']]);flash('Notifications marked as read.');go('notifications');}
 if($path==='/profile/verify-email'){rate_limit('resend-verification:'.$u['id'],2,900);queue_email_verification($u);flash('Verification instructions have been queued for your email address. Contact the administrator if delivery is unavailable.');go('profile');}
 if($path==='/profile'){
 $name=text_input('name',140);$phone=phone_input('phone',false);sql('UPDATE users SET name=?,phone=?,notify_email=?,notify_sms=? WHERE id=?',[$name,$phone,isset($_POST['notify_email'])?1:0,isset($_POST['notify_sms'])?1:0,$u['id']]);audit('account.profile_updated',(int)$u['id']);flash('Profile and preferences saved.');go('profile');
 }
 if($path==='/profile/password'){
 if(!password_verify((string)($_POST['current_password']??''),$u['password_hash']))throw new InvalidArgumentException('The current password is incorrect.');$pass=(string)($_POST['password']??'');password_valid($pass);if($pass!==($_POST['password_confirm']??''))throw new InvalidArgumentException('The new passwords do not match.');sql('UPDATE users SET password_hash=?,auth_version=auth_version+1 WHERE id=?',[password_hash($pass,PASSWORD_DEFAULT),$u['id']]);$_SESSION['auth_version']=(int)$u['auth_version']+1;session_regenerate_id(true);audit('account.password_changed',(int)$u['id']);flash('Password changed. Other signed-in sessions have been revoked.');go('profile');
 }
 if(str_starts_with($path,'/admin/')){require_permission(admin_permission($path));require_once ROOT.'/app/admin_actions.php';admin_post($path,$u);}
 abort_page(404,'Action not found.');
}
